0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:210:\"To thrive in the evolving tech industry, professionals should engage with younger colleagues, embracing their fresh perspectives to foster adaptability, resilience, and ongoing personal and professional growth.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Thu, 08 Oct 2026 14:06:27 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:16:\"Open Channels FM\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:35;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:78:\"Open Channels FM: The Balance of Human Content with the AI Transparency Report\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2563412\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:100:\"https://openchannels.fm/how-open-channels-fm-balances-human-content-with-the-ai-transparency-report/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:101:\"Learn how Bob Dunn chose to create a AI Transparency Report for the Open Channels FM Podcast Network.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Thu, 08 Oct 2026 12:00:34 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"Bob Dunn\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:36;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:87:\"Open Channels FM: Meta Opens Muse to DIY Hardware, GPT-6 Plays WoW Blind, and BootLoops\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2563398\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:92:\"https://openchannels.fm/meta-opens-muse-to-diy-hardware-gpt-6-plays-wow-blind-and-bootloops/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:204:\"Open Channels News host Robert shares AI\'s evolving role, highlighting Meta\'s Home Link for hardware integration, GPT-6 Astra\'s gameplay without visuals, and BootLoops enhancing scientific research tools.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Wed, 07 Oct 2026 15:00:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"Bob Dunn\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:37;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:67:\"WPTavern: #236 – Brian Coords on WordPress as the Source of Truth\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:48:\"https://wptavern.com/?post_type=podcast&p=208932\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:82:\"https://wptavern.com/podcast/236-brian-coords-on-wordpress-as-the-source-of-truth/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:57954:\"<details>Transcript<div>\n<p class=\"wp-block-paragraph\">[00:00:19] <strong>Nathan Wrigley:</strong> Welcome to the Jukebox Podcast from WP Tavern. My name is Nathan Wrigley.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Jukebox is a podcast which is dedicated to all things WordPress. The people, the events, the plugins, the blocks, the themes, and in this case, making WordPress the source of truth across web projects, not just the website.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you&#8217;d like to subscribe to the podcast, you can do that by searching for WP Tavern in your podcast player of choice, or by going to wptavern.com/feed/podcast, and you can copy that URL into most podcast players.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you have a topic that you&#8217;d like us to feature on the podcast, I&#8217;m keen to hear from you and hopefully get you, or your idea, featured on the show. Head to wptavern.com/contact/jukebox and use the form there.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So on the podcast today we have Brian Coords. Brian&#8217;s journey started in teaching and after a surprise detour, thanks to a growing family and a need for new work, he jumped headfirst into WordPress, spending a decade in agency and freelance roles before landing as a developer advocate at WooCommerce. He&#8217;s known for his knack for explaining the complicated parts of WordPress, championing documentation, blogging, podcasting, and bridging the gap between community needs and product development.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Brian recently delivered a talk at WordCamp US entitled, The Site is the Source of Truth, Block Themes, AI and Agency Workflows, and that&#8217;s the focal point for our conversation.</p>\n\n\n\n<p class=\"wp-block-paragraph\">We start with Brian&#8217;s background in both education and development, and how he finds his DevRel role the perfect bridge between those worlds. We then get into the evolution of WordPress from its early days to the present, questioning just what it is that has given the platform such staying power, especially as agencies race to adopt shiny AI tools or static site builders, and are tempted to throw WordPress out with the bath water.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Brian sees unique value in the WordPress ecosystem, especially for sites with longstanding content, integrations, and complex needs. And he makes the case for why the platform is built to last.</p>\n\n\n\n<p class=\"wp-block-paragraph\">We talk through the idea of the site as the source of truth, using WordPress, and increasingly block themes, not only as a publishing platform, but as the repository for all your design, content, and workflow guidelines. Instead of letting generative AI run wild, and potentially cause chaos, Brian outlines how agencies and product teams can centralise approved patterns, templates, and even content guidelines directly in the WordPress site, helping both AI and human users maintain brand and design consistency.</p>\n\n\n\n<p class=\"wp-block-paragraph\">We also unpack the state of block themes, why agency adoption is taking longer than expected? What&#8217;s coming soon for WooCommerce users, and how the move to block-based building is reducing plugin sprawl and making sites more resilient. And of course, we wrestle with the tight rope walk of what should go into WooCommerce Core, versus what is better left to the ecosystem, especially in a world where AI can spin up basic plugins in seconds.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you&#8217;re curious about how WordPress agencies can survive and thrive alongside AI, what the future holds for block themes, and how to build smarter, more sustainable workflows, this episode is for you.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you&#8217;re interested in finding out more, you can find all of the links in the show notes by heading to wptavern.com/podcast where you&#8217;ll find all the other episodes as well.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And so without further delay, I bring you Brian Coords.</p>\n\n\n\n<p class=\"wp-block-paragraph\">I am joined on the podcast by Brian Coords. Hello, Brian.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:04:05] <strong>Brian Coords:</strong> Thank you for having me.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:04:05] <strong>Nathan Wrigley:</strong> Oh, you&#8217;re so welcome. Brian and I were supposed to record this podcast episode at WordCamp US, but, Jamie Marsland.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:04:14] <strong>Brian Coords:</strong> He ruined it, yeah.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:04:16] <strong>Nathan Wrigley:</strong> Yeah, we&#8217;re going to blame him. We had another engagement, which was to watch Jamie Marsland. But I appreciate you giving me the time after your WordCamp US experience. We&#8217;re both back home now.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But if anybody isn&#8217;t familiar with you, Brian, we&#8217;re going to be talking a little bit about a presentation that you did at WordCamp US. That&#8217;s going to be the fulcrum around which the conversation goes. I&#8217;m going to encourage everybody, probably to go and look at the WP Tavern show notes, check them out. We will link to that presentation, which is called The Site is The Source of Truth: Block Themes, AI, and Agency Workflows.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Hopefully gives you some intuition of what we&#8217;re going to talk about. Brian, do you just want to tell the audience a little bit about you? I know it&#8217;s a rather generic question, but tell us about you, your background, lo these many years.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:04:58] <strong>Brian Coords:</strong> Yeah, so currently I work at WooCommerce as a developer advocate, so just working on community documentation, release posts, the blog, all that kind of communication stuff for WooCommerce.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But before that, I spent like 10 years in the agency and freelancer world building WordPress sites, so I leaned on that for WordCamp US. Especially because you can only talk about WooCommerce so much at a WordCamp, so I leaned on my agency background and figured block themes, AI, all this stuff mixing around, what can I try to make sense out of it, and I don&#8217;t know if I did, but I got some thoughts out.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:05:34] <strong>Nathan Wrigley:</strong> I remember a couple of years ago, prior to you getting that job, you were doing various bits and pieces, one of which actually for a tiny period of time was writing for The Tavern. And then I remember you getting the job. I was looking at your profile on social media, I think, and you landed the developer relations job, and I thought, &#8220;Oh, if ever there was a job which fitted a character,&#8221; it felt like you had dropped into something absolutely ideal. Do you just want to tell us what that role actually involves? And is it as ideal as it sounds for somebody of your characteristics?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:06:03] <strong>Brian Coords:</strong> Yeah. To be honest, I saw that that was a type of job that existed in tech, and before I worked in any web development, I was a teacher. I was a high school teacher, so kind of wanted to bring back teaching and writing into what I did as a day job. So I saw that&#8217;s what a developer advocate, that&#8217;s like what DevRel does, and I basically spent like a year or two doing it for free, to prove that I could do it and get a job. And was like, &#8220;I&#8217;ll just pretend to be one, and then eventually somebody will pay me&#8221;,. And that&#8217;s kinda how it worked out.</p>\n\n\n\n<p class=\"wp-block-paragraph\">I mean that&#8217;s basically the job, is you&#8217;re teaching, you&#8217;re doing a lot of writing, you&#8217;re doing a lot of explaining things, you&#8217;re taking a lot of community feedback and bringing it back internally and saying, &#8220;This is what people are asking for, this is what they like or don&#8217;t like about the new feature&#8221;. You&#8217;re just bridging that communication gap, but you are also not responsible for any code, and that&#8217;s the best part of it. I&#8217;m less stressed about code overall.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:06:57] <strong>Nathan Wrigley:</strong> I&#8217;m just going to go totally off piste here because I want to dig into what you said there, because I find that really interesting.</p>\n\n\n\n<p class=\"wp-block-paragraph\">One of the most important pillars of, I think, every society is the education piece, particularly of the younger generation, the children. I have reasons to be into that, but I won&#8217;t share them here. But, very, very meaningful to me.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Do you miss that aspect of life? Obviously there&#8217;s a reason that you stepped away from that. Perhaps it was paperwork or burnout or whatever it may be. But do you miss the kind of face-to-face bit? Because obviously I&#8217;m imagining that you were, there was you, Brian, at the front talking to actual humans who you could reach out and touch if you needed to. How does this map to that, and the desire that you obviously once had to be an educator with real humans inside a real classroom?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:07:39] <strong>Brian Coords:</strong> I left it sort of accidentally. We got pregnant with our first kid and needed to move, and I just needed to find a job closer to home. And it just was an accident, and I stumbled into WordPress and tech and everything. And so, I did miss it and I felt, I think I had an experience where I spoke at a WordCamp and I was like, it felt like teaching, because it was like I know everybody in the room. This is a community, I know everybody, I have a relationship with them. I&#8217;m up in front of the room talking to them, but they&#8217;re also yelling at me and heckling me because we know each other so well.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So it reminded me of that vibe. So I kind of did look for this job as a way to bridge the two things, the WordPress and the tech side, and also a chance to do writing and teaching and bring it back a little bit. And maybe one day I&#8217;ll go back to a classroom or something.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:08:27] <strong>Nathan Wrigley:</strong> Yeah, maybe. One of the curious things that I think about when you see education done well online, you watch somebody&#8217;s YouTube content or wherever that content may land. You sort of get the impression that they just turned on the camera and began. Oh, they&#8217;ve added in some animations, and they&#8217;ve cut and done transitions and things like that.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But for every, let&#8217;s say 30 minutes that you produce online, is there, an hour, two hours, three hours of thinking it through, figuring out the pedagogy, who&#8217;s the audience, how do you write to their skill level? Just talk us through that bit a little bit, and I promise that&#8217;s the last off-piste bit we&#8217;ll do.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:09:03] <strong>Brian Coords:</strong> Yeah, I mean, for everything that I record, I spend a lot of time doing drafts of it. I&#8217;ll try to write the whole thing and just, what would this look like if I wrote the whole thing out?</p>\n\n\n\n<p class=\"wp-block-paragraph\">And then, I&#8217;ve tried doing, a prompter where you read into the camera, and that never feels natural, it doesn&#8217;t work. But if I do three or four takes of it, by the time I get to that fourth take, I&#8217;ve internalized it, and then I can free flow it after that. And that&#8217;s how I approach my talk at WordCamp, where I just kept doing it personally, to the point where I felt like I could just say the stuff naturally.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But I do bring in some of the teaching stuff of thinking about what is the student doing at the time? What are their goals? What is the one thing that they should walk away from this? And I try to bring as much of that into it, but, it&#8217;s hit or miss, you know.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:09:49] <strong>Nathan Wrigley:</strong> Yeah, I guess one of the things that you always were going to miss is the sort of the feedback loop of having people in front of you, you know you&#8217;re, if all the children in front of you are gazing at the floor, then you know you&#8217;ve definitely pitched it incorrectly and you probably need to rethink. But you&#8217;re not necessarily going to get that shooting YouTube videos, but perhaps would, inside of a WordCamp. I can see you nodding, I hope that&#8217;s not actually what&#8217;s happened.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:10:12] <strong>Brian Coords:</strong> Yeah, your YouTube comments are pretty close to being in front of a bunch of middle schoolers, right? That&#8217;s pretty similar. But the face-to-face and being in a real room is important. That&#8217;s why I took this job too, is more WordCamps, more Meetups, more time in person, but also I don&#8217;t have to leave my house every day.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:10:29] <strong>Nathan Wrigley:</strong> Yeah, there is that.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:10:30] <strong>Brian Coords:</strong> I get a balance.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:10:30] <strong>Nathan Wrigley:</strong> That&#8217;s really nice, isn&#8217;t it? Yeah, so you can be working at the time of day that suits you and your family.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Okay, so back on the piste. The title of the presentation, as I said, is The Site is the Source of Truth, Block Themes, AI, and Agency Workflows. I&#8217;m just going to read some of the blurb just so that the listener has context, and it goes like this.</p>\n\n\n\n<p class=\"wp-block-paragraph\">&#8220;Block themes give WordPress an opportunity to become more than a publishing tool or a place where finished designs are implemented. With the right theme structure, patterns, templates, and brand guidelines, a WordPress site can become the source of truth for how new pages and layouts should be built. That matters even more as agencies begin using AI in their build process. AI is useful when it can work from existing pieces, approved patterns, real content, design tokens, reusable blocks, and known template structures. It is much less useful when it starts every landing page from scratch.&#8221;</p>\n\n\n\n<p class=\"wp-block-paragraph\">And it goes on, but I&#8217;ll stop there. Do you want to just summarize what you actually did in that presentation? Then we&#8217;ll dig into the bits and the pieces.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:11:27] <strong>Brian Coords:</strong> Yeah, so you submit the idea for a talk months before a conference, and then you get to the conference and three weeks ahead they tell you, &#8220;Hey, your talk got selected.&#8221; I submitted a couple. That was the one they picked, and then I read all that and I thought, &#8220;Did I write that?&#8221; I couldn&#8217;t even remember writing all that.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But it, the timing actually worked out because we are doing a block theme in Woo right now, and I&#8217;m spending a lot of time focusing on that. It all lined up. But I definitely read that description, and I had already started working on some slides and I thought, &#8220;Oh, I don&#8217;t know how much this lines up to what I actually am presenting.&#8221;</p>\n\n\n\n<p class=\"wp-block-paragraph\">But I think the goal of what I wanted to do is talk about, I feel like a lot of agencies these days are saying, &#8220;We don&#8217;t need WordPress. We&#8217;re moving to static sites. We&#8217;re just letting AI vibe code everything on our sites.&#8221; And I wanted to kind of say there&#8217;s some value in the systems that WordPress has. It&#8217;s maybe a little more work, but there&#8217;s reasons for it.&#8221;</p>\n\n\n\n<p class=\"wp-block-paragraph\">And I ended up doing a history lesson of, &#8220;Here&#8217;s where WordPress started. Here&#8217;s where we took the journey of why things are the way they are, and the benefits for agencies.&#8221; and so I kind of ended up in a place where I got to that topic, but I did a lot of rambling throughout the presentation. I felt like the context was really important. The like, why are we here? Why is WordPress the way it is.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:12:45] <strong>Nathan Wrigley:</strong> Yeah. Okay, that&#8217;s really interesting. So you said there, values in the systems that we have, and we&#8217;ll explore that in a moment. But technology&#8217;s such a weird one, isn&#8217;t it? In that most of the evolution of humans, we come up with ideas and then we finesse them a little bit. We adapt them over time, but it can be, a decade, 100 years before any major improvement takes place. You think the printing press, it just carried on as that printing press for many hundreds of years before it got slightly tweaked with linotype and things like that.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But technology seems to be quite happy to wholesale throw the baby out with the bathwater on a more or less continuous cycle. So, why then do you feel that WordPress should buck that trend in the advent of AI? Like, why does it stand a chance when AI systems are becoming ultra-capable, static sites, or just talk to your agent and it&#8217;ll just build whatever you want. What is it? What&#8217;s the intrinsic value that you think will mean that it will be around in a, I don&#8217;t know, 5 years, 10 years, whatever that may be?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:13:42] <strong>Brian Coords:</strong> Yeah, I think that&#8217;s a question everyone&#8217;s asking, which is, &#8220;Is there a unique value to WordPress that you can&#8217;t replace with AI?&#8221; And I think some people will point to the community and just the ecosystem and the fact that so many solutions already exist. I feel like AI is really good when you have nothing, and you&#8217;re going from zero to one. I have nothing and I&#8217;m going to make something brand new.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Once you get to something where you&#8217;ve had a site for 10 years and it has tons of content and tons of authors and all these integrations and all these sorts of things, AI is helpful, but everything has to move a little slower, everything has to be a little bit more resilient, and those are the places where having a little framework underneath, something like WordPress holding everything together, ends up being a little bit more valuable. But it&#8217;s definitely changing when you would use it, when you would reach for it, and I think that&#8217;s the part people are struggling with right now.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:14:30] <strong>Nathan Wrigley:</strong> Yeah. There&#8217;s so many examples in my life where there&#8217;s a new innovation, but I stick with the older thing, just because it&#8217;s tried and it&#8217;s tested, and I know the limitations of it and I know what I can do with it. So maybe that&#8217;s a good comparison.</p>\n\n\n\n<p class=\"wp-block-paragraph\">It will be interesting to see how AI is able to adapt and just simply build things which are robust and usable. But I think at the moment, the core promise for anybody trying to sell a website to a client, for example, is exactly that. It&#8217;s reliable. It&#8217;s battle tested. It&#8217;s been used on millions of sites all over the world, and it&#8217;s got a familiar interface and you can go in and do this, that, and the other thing, and click save and publish and what have you, and it&#8217;ll just work. Whether or not that remains the case a, a decade from now, I guess only time will tell.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But, have this idea in your presentation of the site being the, and you said the, source of truth. What did you mean by that? What is the underpinning of that? What are the bits that kind of spin off if the WordPress site is the source of truth, what are the bits that sort of rely on that foundation?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:15:28] <strong>Brian Coords:</strong> Yeah, I think one of the things that people see when they start using AI is it will just do whatever it wants. So you could ask it for two pages on your site, and they might look completely different. It might pull in some design trend here. The language might be completely different on this other one. It might not understand your audience and your values.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And so with AI, you end up doing a lot of shepherding that&#8217;s kind of like, &#8220;well, no, this is the target audience. This is my color palette. This is the design things I like to use.&#8221; And so I leaned a lot in the talk to things like patterns in WordPress. Where, it&#8217;s something we do in WooCommerce where we have a designer, they&#8217;re very talented, they make really nice patterns that really conform to our brand. And then AI can go in and say, &#8220;pull the patterns down from the site first and use those. Don&#8217;t spin up crazy new designs. Use the ones that our human designer put a lot of care and effort into, that live in the pattern library on the website.&#8221;</p>\n\n\n\n<p class=\"wp-block-paragraph\">And so the more you put into the website and the more you train AI to, don&#8217;t go crazy and create new things, use the stuff I already have, use the tools I have, that I think makes things a little bit more reliable, a little bit more consistent. And so I think for agencies, finding ways to put stuff into the website that&#8217;s going to help the AI, and guide it directly to doing things the right way. Instead of it always wanting to like, come up with some brand-new chunk of code that you now have to look at. So that was kind of a part of it definitely.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:16:52] <strong>Nathan Wrigley:</strong> So, what you&#8217;re saying there is instead of having all these disparate things like, I don&#8217;t know, you&#8217;ve got a Figma file over there. And you&#8217;ve got a Google document over here. And you&#8217;ve got another three different things and you can&#8217;t really figure out where the heck they are.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Put it all in a WordPress website, and from the point of view of the design, patterns would fit beautifully for that. You can organise your typography, and basic colour palettes, and layouts, and the way things ought to look. And I don&#8217;t know, here&#8217;s two dozen ways that we might structure a page. Lock all of that away. You don&#8217;t necessarily have to publish it anywhere on the front end, but the AI can go and creep around in there and get some guidance.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But then also presumably you could do the same with, I don&#8217;t know, your writing style. You could have draft posts where you outline the manner in which you would like to convey your company. And the words which are off limits, or the words which are definitely going to be used. So in that sense because WordPress can do video, it can do audio, it can do designs, it can do layouts and typography, why not just have that as the source of truth? Is that a sort of summation of what you were saying?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:17:54] <strong>Brian Coords:</strong> Yeah, I think that&#8217;s essentially right. And I talked a little bit about, there&#8217;s a project in WordPress called Content Guidelines, I think, and it does that. Where you put in a lot of your rules. And then I also talked, a lot of agencies use GitHub and Git repos for their WordPress sites, and in there you can do things like having agents files, and skills and stuff that share across your team.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So sometimes it&#8217;s in WordPress, sometimes it&#8217;s in that kind of GitHub code base for your website. So it depends on your agency&#8217;s workflows and stuff. But the point is, everybody puts stuff in the same place, because when I worked at an agency, it was that. It was, they used Figma and they used XD, and they have a Google Doc with all the technical specs, and then there&#8217;s 15 emails from the client. And AI actually is really good at taking all those things and putting it in one place and building a little knowledge base. And then when you bring on another developer, their AI is going to know exactly where that is, and it&#8217;s going to make things a little bit more scalable.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So it&#8217;s just an organizational principle, like just cleaning things up, putting stuff in one space, and making WordPress sort of the home for that, instead of using all these different tools that maybe you don&#8217;t need, or maybe you&#8217;re going to lose access to.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:19:00] <strong>Nathan Wrigley:</strong> I can&#8217;t remember the name, I think you just called it content guidelines or something like that. I can&#8217;t remember the name of that project, and I also can&#8217;t remember whether the intention is to ship that in Core at some point.</p>\n\n\n\n<p class=\"wp-block-paragraph\">That seems like a really curious idea. Presumably it&#8217;s a non-public facing repository of, I&#8217;m doing air quotes, &#8220;stuff&#8221;. So you just dump into there all of the different bits and pieces. Presumably by trial and error over many iterations, you&#8217;ll figure out exactly what the agent&#8217;s creeping around in your site, and that content guidelines portion of your site is going to be able to take from that.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And you would amend it, and then when you begin another client site, that would be your first port of call. Get your client guidelines figured out, get that set of constraints worked out, and then move on with the design process.</p>\n\n\n\n<p class=\"wp-block-paragraph\">That&#8217;s a really neat idea. Somewhat hidden from the public, but pretty neat. Now, I don&#8217;t really deal with agencies. I don&#8217;t have any communication with them. Do you have a sense that they&#8217;re open to these ideas, or it&#8217;s just some sort of curiosity which the core team think they might ship, but who knows whether anybody will use it? Have you got intuitions that this would be used?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:20:00] <strong>Brian Coords:</strong> Yeah, that&#8217;s been an interesting one. That content guidelines feature almost shipped, and then it got pulled at the last minute and was kind of like, &#8220;Let&#8217;s see some real world usage of this.&#8221; I think it&#8217;s probably really helpful for big news publications. That&#8217;s what I&#8217;ve heard a lot of. Where they have 20 authors and they want to make sure their authors are doing the right thing, and so that makes sense.</p>\n\n\n\n<p class=\"wp-block-paragraph\">I think for agencies, a lot of the ones I talk to, they really, they like putting things in GitHub. That&#8217;s where they like to put stuff, and they like putting it in the code. I don&#8217;t know if they&#8217;ll put it in WordPress, but I think it&#8217;ll be interesting to see. But I feel like we&#8217;re all just dealing with, there&#8217;s just tons of content, and markdown files, and prompts and skills and all these overwhelming amounts of things, and it&#8217;s like everybody together is trying to figure out what are the best ways to do this. And I think it&#8217;s just fun to explore the ideas and see. In two years maybe we&#8217;ll all have the answer to this.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:20:54] <strong>Nathan Wrigley:</strong> Yeah. We&#8217;ll have a fresh set of new problems in two years.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:20:57] <strong>Brian Coords:</strong> Yeah.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:20:57] <strong>Nathan Wrigley:</strong> It was curious there, we&#8217;d been talking about AI for a while and then when you, corroborated your examples there, you described the humans using it, which I thought was quite interesting. So you&#8217;ve got these 20 people working for, let&#8217;s say, TechCrunch or something like that. Big organization, lots of editors, lots of authors and what have you. But even if the AI never touches base on that, just the idea that the humans can access it in a human-readable way, not all about the AI.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Just that seems worth shipping. If all that you do is have some mechanism to show brand new author to techcrunch.com, how you would like things to look and feel and what have you, that seems like a reason to ship it even if the AI portion isn&#8217;t launched at the beginning.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:21:38] <strong>Brian Coords:</strong> I think everybody&#8217;s explored, I know I did, where you go all in on AI and it&#8217;s going to write all my stuff, and it&#8217;s going to do all these things for me. And then internally we&#8217;ve had a, I forget what the post, but somebody wrote this kind of, writing is for humans post, and a lot of people in the company rallied around that. Which is like, it was fun to let AI do some stuff, but writing is important, and writing should be done by humans. We don&#8217;t want to put AI content out. So at the end of the day, we expect humans to write, and we still really value that, and writing is a valuable thing in and of itself.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But then AI can come in a little later and say, &#8220;Well, maybe I&#8217;ll review it for you. Maybe I&#8217;ll give you some feedback and you can take it or not.&#8221; But it&#8217;s been an interesting, I feel like there was a pendulum where AI will do everything, and now it&#8217;s like, no, I think we&#8217;ll find the places for it to make things move faster, but there&#8217;s just still human value, and I&#8217;m glad to see that pendulum maybe coming back, at least internally for us it is.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:22:34] <strong>Nathan Wrigley:</strong> Sorry, going slightly off piste here, but I have an intuition that by the time another decade has passed, I think there is a version of the universe in which people have become really sick and tired of AI. I think it&#8217;s a really plausible future that some things will be viewed with enormous incredulity and skepticism if there&#8217;s any hint of it being done by an AI.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So perhaps that won&#8217;t be design. Perhaps it won&#8217;t be music. Perhaps it won&#8217;t be coding. But I&#8217;ve got a feeling that writing, especially fictional writing and things like that, but also opinion pieces and things, I think that is highly likely to become, once again, the domain of a human being. And I know for certain that my own children are very skeptical about AI and the future that&#8217;s presenting. So yeah, I welcome that commentary. I&#8217;ll leave it there if you&#8217;ve got anything to follow up with. If not, I&#8217;ll ask another question.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:23:22] <strong>Brian Coords:</strong> Yeah, I go back and forth on it. I&#8217;ve never listened to AI music, and I don&#8217;t think I ever will.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:23:28] <strong>Nathan Wrigley:</strong> No.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:23:29] <strong>Brian Coords:</strong> Maybe I have and I just don&#8217;t know it.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:23:31] <strong>Nathan Wrigley:</strong> Curiously, I bet you have. Yeah.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:23:32] <strong>Brian Coords:</strong> Yeah, I probably have. AI writing is the same way. It&#8217;s if you can&#8217;t tell that it&#8217;s AI, will that matter? And I think at the end of the day it will, because I don&#8217;t read things unless I know who the author is and I&#8217;m interested in their perspective, and I don&#8217;t really listen to music if I don&#8217;t know, I like to know the story of the band, and I like to know the context. If I&#8217;m reading a book, I like to know when the author lived and what culture they&#8217;re filtering everything through and, yeah, maybe we&#8217;ll be unique and some people will just want to doom scroll AI videos of cats, but I never did that before, so I don&#8217;t know if I&#8217;ll do it starting now.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:24:05] <strong>Nathan Wrigley:</strong> No, but curiously, it might offer a slight marketing edge, let&#8217;s put it that way. If you can certify provably that you are the real thing. Whether that be in the music space and you simply have to record the process of you going through the process of creating a song with all of the mistakes, and heartache, and anguish that that is.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But I feel that maybe there will be a craving for that in the future. Maybe people will literally work harder to find people online who are provably writing their own material, be that songs or making videos or writing and what have you.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So we&#8217;ve all been swamped AI and been beguiled by it, I think as you&#8217;ve said, the pendulum feels like there&#8217;s a bit of a swing in the other direction, and it might be that you can have a marketing edge simply because you&#8217;re actually taking the time to, to write things out. So anyway, there you go.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Let&#8217;s move on slightly. So block themes. You were mentioning that at Woo you&#8217;re currently playing with a block theme. I don&#8217;t know how many of those are actually in the bag already and out there in the wild coming directly from Woo. But it does feel that many years ago block themes were being touted as the thing.</p>\n\n\n\n<p class=\"wp-block-paragraph\">It feels like it didn&#8217;t turn out quite the way we expected. There hasn&#8217;t been this deluge of block themes, and everybody&#8217;s put the classic themes behind them. I think people are clinging to classic themes for a variety of reasons. Do you want to just talk about why you think block themes fit into this whole agency source of truth piece as well?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:25:28] <strong>Brian Coords:</strong> Yeah, block themes have been interesting. I&#8217;ve seen a lot of agencies that really start to like them, and agencies understand the value. I think, for a lot of existing websites, just changing your theme is hard. There has to be a really good reason to change your theme, because who knows what&#8217;s going to break? Who knows how everything is going to work, especially with e-commerce? It&#8217;s like if it&#8217;s not broken, don&#8217;t touch it. There better be a good reason for it.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And so I think in some ways for a lot of people, block themes for existing sites maybe haven&#8217;t given them a really good reason to switch yet. But I think it will for a number of reasons. I was actually just talking to a coworker about our block theme that we&#8217;re getting ready to launch. Probably by the time this is out, it might be in a public beta.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But one of the things that was interesting is in WooCommerce, there was a theme called Storefront, which was like, that was the WooCommerce theme. And we&#8217;re doing a comparison right now, where if you wanted to move from Storefront to our block theme, Storefront had all these plugins. A plugin to do a header on your site, and a plugin to do a little mini cart, and a plugin to do product carousels, and all these plugins you would have to install. And that meant testing them and making sure they work and updating.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And we did a comparison of how many of these things can you already just do in the block editor, and it was like 90% of it already exists in the block editor. And you don&#8217;t need a plugin for it, and you don&#8217;t need extra code, and you don&#8217;t need to buy a new extension. So I think people are starting to see the value of it, once they realize how much is just included. I can change anything. I don&#8217;t need a plugin to add this or that to my site.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So I think there&#8217;s a lot of value to it, and it just ends up being a little safer because it&#8217;s just WordPress and WooCommerce and a theme that only has a little bit of styling. I&#8217;m not worried about the compatibility of plugins, and I&#8217;m not worried about paying for updates and all these sorts of things, and is it going to break on the next version?</p>\n\n\n\n<p class=\"wp-block-paragraph\">And so I think there&#8217;s a lot of value to it, and it just makes WordPress itself more the thing you&#8217;re relying on. You&#8217;re just relying on the blocks. You&#8217;re just relying on the things that WordPress gives you. So I think there&#8217;s going to be a lot of benefits to it, but yeah, we have not, there is no WooCommerce official block theme yet, but we&#8217;re hoping that there will be one soon.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:27:31] <strong>Nathan Wrigley:</strong> One of the things that I thought block themes would tackle really quickly soon after launching, which never kind of ended up being the case, was for example, things like WooCommerce, atomising every bit of a WooCommerce site into a separate, let&#8217;s say block. So for example, I don&#8217;t know, the add to cart block, and the the I don&#8217;t know, show the quantity in the cart in the menu block, and yada, yada.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And you go to the cart page or the payment page, and you would just fill it up with the blocks as you&#8217;d like, and add spacing and add margins and what have you. That never seemed to take off, but also I don&#8217;t know if it&#8217;s still talked about, or the promise of that is still something that you are hoping to deliver.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Just talk us through where we&#8217;re at in terms of atomising the entirety of a WooCommerce site into individual blocks. So rather than dropping entire sort of templates or structures, you can pick and cherry pick. obviously there&#8217;d be dependencies. If you&#8217;ve got this, you must have that. But just tell us where we&#8217;re at.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:28:28] <strong>Brian Coords:</strong> Yeah, so overall you can do that for most of a store. I think the only thing that doesn&#8217;t have blocks right now at all is like the account pages. Somebody logs in and they see their downloads and their order history and all that. That stuff is, I don&#8217;t even think is anywhere blocks at all. But that was one of the things as part of this process is, we looked at all the blocks, because there is a add to cart button block, and there is a quantity selector block, and there is a product image gallery block. I mean there&#8217;s like a, more than 100, maybe 200 blocks in WooCommerce.</p>\n\n\n\n<p class=\"wp-block-paragraph\">There&#8217;s a lot, but the thing that they were missing was the style controls, which is I think what a lot of people wanted. Which is if I have the button, is it going to look like every other button on my site? And can I customize it? Are all the form inputs on my checkout page going to look just like the drop down on my product selection page?</p>\n\n\n\n<p class=\"wp-block-paragraph\">And so that&#8217;s been the big push recently, like actually building the block theme, like 90% of the work of what they&#8217;re doing is just fixing the blocks, and making the blocks better. And the theme is just a very thin layer.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So it&#8217;s gotten a lot better, and that&#8217;s kind of the goal is once we have our own theme we can show, okay, all this stuff is customizable and editable. And I think probably in the next release you&#8217;ll see a huge focus on those block style changes showing up in WooCommerce.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:29:44] <strong>Nathan Wrigley:</strong> I have a curious question that you may or may not wish to answer. Let&#8217;s see how this one goes. If you, as you just described, you were talking about you don&#8217;t need a plugin for that. You don&#8217;t need to worry about an update or a payment for this thing. We&#8217;re bringing all that functionality into Core.</p>\n\n\n\n<p class=\"wp-block-paragraph\">I&#8217;m wondering what that tightrope looks like, where over there somewhere, part of the community, somebody&#8217;s got a paid plugin, which is the basis of their entire livelihood. But it just so happens that, we could really ship that in Core, and that would be really useful to have in Core. We reckon that 80% of the people who use WooCommerce will use that.</p>\n\n\n\n<p class=\"wp-block-paragraph\">How do you decide when something gets made and the obvious sort of community impact that that thing may have had? So as I said, that&#8217;s a tricky question. I will leave you to answer it or not.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:30:31] <strong>Brian Coords:</strong> Yeah, it is a huge topic of discussion. James Kemp, who is the Core product lead has been pushing for more of these things in Core. And I think that the big question right now is, are a lot of the people making money on plugins going to be able to continue making money on some of those plugins with AI? Because there&#8217;s a lot of plugins that are 100 lines of code that an AI will happily spit out for you.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And so I think the floor is raising on people building plugins. Where if your plugin isn&#8217;t doing anything super complicated, if it&#8217;s set it and forget it, then there&#8217;s probably not going to be a market for it in the future.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But that said, there&#8217;s this whole other area of opportunity where there&#8217;s tons of plugins that need to be built still. There&#8217;s integrations that are really complicated that you don&#8217;t want to leave to AI. There&#8217;s things around modifying payments and modifying how your checkout works and different types of products. And all of that stuff I think is still available, and I think most people will choose to pay for those sorts of things.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But if your plugin is something, I will just say we&#8217;ve, all the ones we&#8217;ve brought in are our own plugins so far. So this new WooCommerce release that&#8217;s coming out this week is different product variations can have image galleries on each variation. That&#8217;s a thing. But that was our plugin. So we took our plugin and we put it in Core, and gave it away for free. We don&#8217;t really try to go after if somebody&#8217;s got an established community plugin and they&#8217;re supporting it. We don&#8217;t want to go after them. But we are definitely cannibalizing a few of our own plugins, and turning off a little bit of revenue we get from those to put those in Core. And that&#8217;s, we think it&#8217;s worth it in the long run to just have a better WooCommerce.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:32:09] <strong>Nathan Wrigley:</strong> I think that&#8217;s a really difficult tightrope to walk, isn&#8217;t it? Because obviously you would love to have every piece of functionality available in a, you know, easy to use manner in Core, or at least all the bits and pieces that were essential. But at the same time, there&#8217;s this delicate balancing act of the community, which at the moment seems to be, how shall we say it, in a holding pattern? Let&#8217;s go with that.</p>\n\n\n\n<p class=\"wp-block-paragraph\">There&#8217;s a lot of uncertainty, people who have this sort of utility plugin that does this one thing, as you&#8217;ve described, it may be 100, 200 lines of code. Where in the past that was probably going to make you some nice pocket change. It does feel like that is going away.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So if that is the calculus upon which you&#8217;re basing whether you build something into Core or not, you&#8217;re potentially swooping in and creating something for which there is no business anymore anyway, Because now in the advent of AI, anybody with half a minute can whip that same functionality up, and you might as well have it all security checked and what have you inside of Core.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But very difficult to figure out how to balance damaging, I suppose, is the wrong word, but it&#8217;s adjacent to what I&#8217;m after. Damaging relations with community members who are great great advertisements for building on top of WooCommerce, and yet shipping all these things in Core. Difficult. I&#8217;m glad, I don&#8217;t have to square that circle.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:33:23] <strong>Brian Coords:</strong> Yeah, and we have a very vocal extension developer community. They give us feedback all the time. And some of them, I think they&#8217;re well aware that they&#8217;re much more likely to be threatened by AI, than they are us wanting the functionality of their plugin in Core.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But there&#8217;s also a general sense in WooCommerce from, like the customers, which is, &#8220;Why do I need so many plugins?&#8221; And that&#8217;s kind of a concern and that fear of, when I update WooCommerce and I have 30 to 50 extensions, which is very normal for a WooCommerce store, is each one of those going to work? Do I have to worry about that?</p>\n\n\n\n<p class=\"wp-block-paragraph\">And so it is also a balance where it&#8217;s almost damaging WooCommerce that you need so many plugins just to run a store. And that why do I need a plugin for this and this, you know? So we&#8217;re trying to balance that, where we want to make it feel more secure and reliable.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But also I think a lot of those plugins are much more threatened by AI than they are us getting around. We have plenty to work on before we get around to taking other people&#8217;s plugins. We have plenty to work on our own to improve basically WooCommerce, subscriptions, all the kind of Core stuff we already manage.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:34:25] <strong>Nathan Wrigley:</strong> Yeah, I feel that in the WordPress space, the most likely bit to survive, is potentially WooCommerce. Just simply because there is so much that is at stake by messing up your website by injecting a bunch of AI slop. Again, I&#8217;m doing air quotes.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Because, this is your revenue. If you take your site down for half a minute, that really could lose you, I don&#8217;t know, thousands of dollars in orders. But I don&#8217;t know if that&#8217;s your intuition as well. It feels like brochure sites, that is very much up for debate at the moment. We&#8217;ll have to see how the landscape goes with that. But it feels like the WooCommerce bit, the e-commerce of WordPress&#8217;s community, it feels like you&#8217;re on a bit of safer ground just simply because of the revenue that&#8217;s generated by those sites and the reluctance of people to meddle with them.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:35:14] <strong>Brian Coords:</strong> Yeah. I mean that&#8217;s what I&#8217;ve been yelling internally, so I&#8217;m glad you agree. I think e-commerce is definitely much more, has a much stronger moat than static brochure sites. And I think that&#8217;s what people in WordPress are sort of dealing with, which is for all these sites that are on WordPress how many of them need WordPress? How many of them need this functionality? WooCommerce definitely. You need a database, and you need security, and you need updates and you need all this stuff.</p>\n\n\n\n<p class=\"wp-block-paragraph\">For a marketing brochure site, you probably didn&#8217;t need it to begin with, but WordPress was easier. So the question is for those simple marketing sites, do we make WordPress easier so that they can keep using WordPress, or do we say, &#8220;No, we&#8217;re going to lean in on publishing, commerce, really complicated, heavier duty sites that probably generate more money, but maybe the total market share goes down,&#8221; I don&#8217;t know. I think that is a big question.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:36:05] <strong>Nathan Wrigley:</strong> Yeah, it&#8217;s interesting. I can imagine in a decade from now, the UI for a typical brochure site almost not even a UI. It&#8217;s something that we can&#8217;t really conceive of at the moment. It might be that, you speak to a thing, and the thing reacts and amends as necessary. Maybe WordPress will have to fight that territory to keep its market share.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But I do feel that the WooCommerce side, I think people are going to be able to justify the time put in to logging into a platform and going through a list of products and adding, &#8220;Okay, I&#8217;ve got some shoes that I&#8217;m selling over here and they come in seven different varieties. I want to sell the shoes. I&#8217;m going to upload the color palettes for each of those shoe,&#8221;. There&#8217;s just some calculus of the work that needs to be done and the maintenance that needs to be done. I feel that you&#8217;re on much, much stronger ground as you described. So yeah, I think you&#8217;ve every reason to be sanguine.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:36:52] <strong>Brian Coords:</strong> Yeah, and I still think people want to log in to something and look at something. Especially with e-commerce, they want to just see a screen of how their orders are doing. They don&#8217;t want to ask AI to generate that every single second that they want to see how many orders they have, and what their revenue is for that day and all their analytics. They just want to log in and see the thing that they see every day. They don&#8217;t need to vibe code that on the fly by asking AI to generate it, right?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:37:15] <strong>Nathan Wrigley:</strong> Do you know that&#8217;s really interesting? I have genuinely never thought about the desire to log into a thing, but that actually makes a lot of sense to me.</p>\n\n\n\n<p class=\"wp-block-paragraph\">This is going to sound extremely out there, but I&#8217;m going to say it anyway. There is something of akin to getting home when you&#8217;ve been on a long journey, and you finally get to your own front door after sleeping in hotels, beds, and all of that. There&#8217;s just something quite nice about getting into you own environment and it&#8217;s, &#8220;Ah, I&#8217;m at home.&#8221;</p>\n\n\n\n<p class=\"wp-block-paragraph\">And I actually have started blogging again recently, and I get a real great feeling when I log in and all that familiar stuff is there, and, &#8220;Oh, look, there&#8217;s all the pictures that I&#8217;ve posted on this website these many years.&#8221; I think there&#8217;s something there. I think that&#8217;s really curious. The idea of logging into something, being purposeful about it. Not speaking to the exact same interface that you talk to every other thing to do the job. Having a place, a URL that you go to, the environments how you&#8217;ve set it up, I can&#8217;t believe I&#8217;ve never thought of that before, but I think that&#8217;s quite profound. I hope you&#8217;re right.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:38:18] <strong>Brian Coords:</strong> Yeah. I hope I&#8217;m right too. I hope that there&#8217;s just some things in life you don&#8217;t want to ask an agent to go do for you, and you just say, &#8220;Let me just click on this and change this thing.&#8221; Some things are just faster than, &#8220;All right, I&#8217;m going to text my agent, and hopefully he does it right, and then he&#8217;s going to send me a screenshot that it got done.&#8221; I mean, I love doing that kind of stuff. I do it for some things, but yeah, sometimes you&#8217;re just, &#8220;show me that same dashboard.&#8221;</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:38:41] <strong>Nathan Wrigley:</strong> Yeah. And I do wonder in the years to come how ready we are going to be to submit all of that control. Just the idea that an essential part of your business, like your e-commerce site could be done by an AI with very little intuition as to what&#8217;s happening once that command has been given and it updates that stuff.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But not just that you don&#8217;t know what that thing did, what the thousand other things that were done prior to that one prompt. Okay, it looks nice at the minute, but how did it even get there? Well that was about two years of prompting. Okay. All right. Can we unpick that? Not really. We haven&#8217;t the faintest idea how it got to this. Yeah, that&#8217;s really interesting. Okay. I think I&#8217;ve asked everything I wish to ask. Is there anything you wanted to get out before we knock it on the head, Brian?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:39:24] <strong>Brian Coords:</strong> No, just hopefully we&#8217;re still here in five years, not just prompting away in our basements.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:39:29] <strong>Nathan Wrigley:</strong> You know what? I think if you&#8217;d have asked me that question six months ago, I had less certainty than I do now. I think I&#8217;ve seen a sort of, tsunami is the wrong word, it certainly is not that, but a general sense out in the world at at large of distrust and a move towards the sort of more artisan side of life.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And so I think it&#8217;ll be curious to revisit this conversation in a few years time and see how that pendulum has swung. If the AI overlords are listening to this in the year 2028, please do not come and get me. I was wrong. But there we go. Let&#8217;s hope that we&#8217;ve all got somewhere to stand, a beachhead to stand in a few years. That&#8217;d be nice to think about.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Okay, Brian, thank you so much for chatting to me today. I really appreciate it.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:40:10] <strong>Brian Coords:</strong> Thank you.</p>\n</div></details>\n\n\n\n<p class=\"wp-block-paragraph\">On the podcast today we have <a href=\"https://profiles.wordpress.org/bacoords/\">Brian Coords</a>.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Brian’s journey started in teaching, and after a surprise detour, thanks to a growing family and a need for new work, he jumped headfirst into WordPress, spending a decade in agency and freelance roles before landing as a Developer Advocate at WooCommerce. He’s known for his knack for explaining the complicated parts of WordPress, championing documentation, blogging, podcasting, and bridging the gap between community needs and product development.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Brian recently delivered a talk at WordCamp US entitled “The Site Is the Source of Truth: Block Themes, AI, and Agency Workflows,” and that’s the focal point for our conversation. We start with Brian’s background in both education and development, and how he finds his DevRel role the perfect bridge between those worlds.</p>\n\n\n\n<p class=\"wp-block-paragraph\">We then get into the evolution of WordPress, from its early days to the present, questioning just what it is that has given the platform such staying power, especially as agencies race to adopt shiny AI tools or static site builders and are tempted to throw WordPress out with the bathwater. Brian sees unique value in the WordPress ecosystem, especially for sites with longstanding content, integrations, and complex needs, and he makes the case for why the platform is built to last.</p>\n\n\n\n<p class=\"wp-block-paragraph\">We talk through the idea of ‘the site as the source of truth’, using WordPress (and increasingly block themes) not only as a publishing platform, but as the repository for all your design, content, and workflow guidelines. Instead of letting generative AI run wild (and potentially create chaos), Brian outlines how agencies and product teams can centralise approved patterns, templates, and even content guidelines directly in the WordPress site, helping both AI and human users maintain brand and design consistency.</p>\n\n\n\n<p class=\"wp-block-paragraph\">We also unpack the state of block themes, why agency adoption has taken longer than expected, what’s coming soon for WooCommerce users, and how the move to block-based building is reducing plugin sprawl and making sites more resilient. And, of course, we wrestle with the tightrope walk of what should go into WooCommerce Core versus what is better left to the ecosystem, especially in a world where AI can spin up basic plugins in seconds.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you’re curious about how WordPress agencies can survive and thrive alongside AI, what the future holds for block themes, and how to build smarter, more sustainable workflows, this episode is for you.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Useful links</h2>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://www.briancoords.com\">Brian&#8217;s website</a></p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://us.wordcamp.org/2026/session/the-site-is-the-source-of-truth-block-themes-ai-and-agency-workflows/\">The Site Is the Source of Truth: Block Themes, AI, and Agency Workflows</a> &#8211; Brian&#8217;s presentation at WordCamp US 2026</p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://woocommerce.com\">WooCommerce</a></p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://make.wordpress.org/ai/2026/02/03/content-guidelines-a-gutenberg-experiment/\">Content Guidelines: A Gutenberg Experiment</a></p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Wed, 07 Oct 2026 13:00:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:14:\"Nathan Wrigley\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:38;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:54:\"Akismet: Upgrade to the official Akismet Drupal module\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:28:\"http://akismet.com/?p=285183\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:71:\"https://akismet.com/blog/upgrade-to-the-official-akismet-drupal-module/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:8721:\"<figure class=\"wp-block-image size-large\"><img alt=\"\" class=\"wp-image-285267\" height=\"537\" src=\"https://akismet.com/wp-content/uploads/2026/10/akismet-and-drupal-integration-banner.png?w=1024\" width=\"1024\" /></figure>\n\n\n\n<p class=\"wp-block-paragraph\">If your Drupal site still runs the community Akismet module (<code>drupal/akismet</code>), the official Akismet module (<code>drupal/akismet_antispam</code>) can upgrade it in place. You swap the Composer package, run database updates, and your API key and protection settings come along. We built it so you don&#8217;t have to uninstall, reinstall, and re-enter everything. This post walks through the steps.</p>\n\n\n\n<h3 class=\"wp-block-heading\" id=\"which-sites-this-covers\">Which sites this covers</h3>\n\n\n\n<p class=\"wp-block-paragraph\">The update needs Drupal 10.3 or later on PHP 8.1 or later. That covers sites on the community module&#8217;s 2.0.x releases and its 8.x-1.x dev branch.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you&#8217;re on an older setup:</p>\n\n\n\n<ul class=\"wp-block-list\">\n<li><strong>8.x-1.0-alpha2 (Drupal 8 or 9):</strong> update the community module to 2.0.0-alpha2 while you update core, then follow this post.</li>\n\n\n\n<li><strong>7.x:</strong> upgrade Drupal first, then install the official module fresh. Your Akismet account and API key still work.</li>\n</ul>\n\n\n\n<p class=\"wp-block-paragraph\">The <a href=\"https://www.drupal.org/docs/extending-drupal/contributed-modules/contributed-module-documentation/akismet-anti-spam/migrating-from-the-community-akismet-module\">migration guide on drupal.org</a> has a table for every release if you&#8217;re not sure which one you run.</p>\n\n\n\n<h3 class=\"wp-block-heading\" id=\"before-you-start\">Before you start</h3>\n\n\n\n<ul class=\"wp-block-list\">\n<li><strong>Back up the database.</strong> The update only goes one way.</li>\n\n\n\n<li><strong>Note which roles have &#8220;Bypass Akismet protection.&#8221;</strong> The update removes that permission (more on that below).</li>\n\n\n\n<li><strong>Plan one deploy for the whole swap.</strong> Between the Composer change and <code>drush updb</code>, spam protection is off and some admin pages break, so don&#8217;t leave a gap between them.</li>\n</ul>\n\n\n\n<h3 class=\"wp-block-heading\">What carries over, and what doesn&#8217;t</h3>\n\n\n\n<p class=\"wp-block-paragraph\">These come along:</p>\n\n\n\n<ul class=\"wp-block-list\">\n<li>Your API key</li>\n\n\n\n<li>Your connection timeout, if it&#8217;s between 1 and 60 seconds</li>\n\n\n\n<li>Your comment, contact and registration protection settings</li>\n</ul>\n\n\n\n<p class=\"wp-block-paragraph\">These don&#8217;t:</p>\n\n\n\n<ul class=\"wp-block-list\">\n<li><strong>Check history.</strong> The community module&#8217;s <code>akismet</code> table is dropped, so the Spam tab starts empty. Those rows hold submitted content, including author emails and IP addresses, and the official module has no way to erase them later. </li>\n\n\n\n<li><strong>Per-form settings.</strong> The community module could protect some comment types or contact forms and not others. The official module has one toggle per category, and it covers all of them.</li>\n\n\n\n<li><strong>Per-form &#8220;discard spam.&#8221;</strong> This becomes one site-wide strictness setting.</li>\n\n\n\n<li><strong>Test mode, custom API endpoints and the &#8220;block all submissions&#8221; outage policy.</strong></li>\n\n\n\n<li><strong>The &#8220;Bypass Akismet protection&#8221; permission.</strong> The update removes it from every role that had it. The official module&#8217;s equivalent is <code>bypass akismet</code>, and it isn&#8217;t granted automatically.</li>\n\n\n\n<li><strong>Webform handlers.</strong> You&#8217;ll need to re-attach the Akismet handler to each webform that used it.</li>\n</ul>\n\n\n\n<p class=\"wp-block-paragraph\">You don&#8217;t have to track any of this by hand. The update prints a report that names every item above that applies to your site.</p>\n\n\n\n<h3 class=\"wp-block-heading\" id=\"the-migration\">The migration</h3>\n\n\n<div class=\"wp-block-code\">\n	<div class=\"cm-editor\">\n		<div class=\"cm-scroller\">\n			\n<pre>\n<code class=\"language-shell\"><div class=\"cm-line\">composer remove drupal/akismet</div><div class=\"cm-line\">composer require drupal/akismet_antispam <span class=\"tok-propertyName\">-W</span></div><div class=\"cm-line\">drush cr</div><div class=\"cm-line\">drush updb</div></code></pre>\n		</div>\n	</div>\n</div>\n\n\n<p class=\"wp-block-paragraph\">Run them in that order, back to back.</p>\n\n\n\n<ol class=\"wp-block-list\">\n<li><strong><code>composer remove</code></strong> first, and leave the module installed in Drupal. Don&#8217;t uninstall it, because the update reads its database state. The official module&#8217;s <code>composer.json</code> conflicts with <code>drupal/akismet</code>, so Composer won&#8217;t install them side by side.</li>\n\n\n\n<li><strong><code>composer require ... -W</code></strong> lets Composer update shared dependencies, like the Akismet PHP SDK or the PSR HTTP packages, if your lock file pins an older version. Without <code>-W</code>, Composer can refuse with &#8220;the package is fixed to &#8230; (lock file version).&#8221;</li>\n\n\n\n<li><strong><code>drush cr</code></strong> before anything else. The community module shipped services that no longer exist, and Drupal still has them cached. Until you rebuild, logged-in pages return a 500 and drush commands die on shutdown. <code>drush cr</code> works when nothing else does.</li>\n\n\n\n<li><strong><code>drush updb</code></strong> runs the update. Stay off the comment admin screens until it finishes.</li>\n</ol>\n\n\n\n		<figure class=\"wp-block-jetpack-videopress jetpack-videopress-player\">\n			<div class=\"jetpack-videopress-player__wrapper\"> <div class=\"jetpack-video-wrapper\"></div></div>\n			\n			\n		</figure>\n		\n\n\n<p class=\"wp-block-paragraph\">Read the report. It&#8217;s also logged to watchdog, so you won&#8217;t lose it if your terminal scrolls away. Then export and commit the new configuration:</p>\n\n\n<div class=\"wp-block-code\">\n	<div class=\"cm-editor\">\n		<div class=\"cm-scroller\">\n			\n<pre>\n<code class=\"language-shell\"><div class=\"cm-line\">drush cex</div></code></pre>\n		</div>\n	</div>\n</div>\n\n\n<p class=\"wp-block-paragraph\">On every other environment, rebuild the cache before anything else touches it:</p>\n\n\n<div class=\"wp-block-code\">\n	<div class=\"cm-editor\">\n		<div class=\"cm-scroller\">\n			\n<pre>\n<code class=\"language-shell\"><div class=\"cm-line\">drush cr &amp;&amp; drush deploy</div></code></pre>\n		</div>\n	</div>\n</div>\n\n\n<h3 class=\"wp-block-heading\" id=\"check-that-it-worked\">Check that it worked</h3>\n\n\n\n<ul class=\"wp-block-list\">\n<li><strong>Settings:</strong> confirm your protection toggles at <code>/admin/config/content/akismet</code>.</li>\n\n\n\n<li><strong>Status report:</strong> check the Akismet entries at <code>/admin/reports/status</code>.</li>\n\n\n\n<li><strong>Test submission:</strong> post a comment as an anonymous user named <code>akismet-guaranteed-spam</code>. Akismet always flags that name, so the comment should land in the Spam tab.</li>\n</ul>\n\n\n\n<h3 class=\"wp-block-heading\" id=\"already-on-the-official-module-1-0\">Already on the official module 1.0?</h3>\n\n\n\n<p class=\"wp-block-paragraph\">Upgrading to 1.1 is one command and a database update:</p>\n\n\n<div class=\"wp-block-code\">\n	<div class=\"cm-editor\">\n		<div class=\"cm-scroller\">\n			\n<pre>\n<code class=\"language-shell\"><div class=\"cm-line\">composer update drupal/akismet_antispam <span class=\"tok-propertyName\">-W</span></div><div class=\"cm-line\">drush updb</div></code></pre>\n		</div>\n	</div>\n</div>\n\n\n<p class=\"wp-block-paragraph\">The <code>-W</code> matters here. Version 1.1 needs Akismet PHP SDK 1.5, and if your lock file still pins 1.4, Composer stops with:</p>\n\n\n<div class=\"wp-block-code\">\n	<div class=\"cm-editor\">\n		<div class=\"cm-scroller\">\n			\n<pre>\n<code><div class=\"cm-line\">drupal/akismet_antispam 1.1.0 requires automattic/akismet-sdk ^1.5 -&gt; found automattic/akismet-sdk[v1.5.0] but the package is fixed to v1.4.0 (lock file version).</div></code></pre>\n		</div>\n	</div>\n</div>\n\n\n<p class=\"wp-block-paragraph\"><code>-W</code> (short for <code>--with-dependencies</code>) lets Composer update the SDK along with the module.</p>\n\n\n\n<h3 class=\"wp-block-heading\" id=\"questions\">Questions</h3>\n\n\n\n<p class=\"wp-block-paragraph\">If something in the report surprises you, or the update doesn&#8217;t go the way this post says, open an issue in the <a href=\"https://www.drupal.org/project/issues/akismet_antispam\">issue queue</a>. The <a href=\"https://www.drupal.org/docs/extending-drupal/contributed-modules/contributed-module-documentation/akismet-anti-spam/migrating-from-the-community-akismet-module\">migration guide</a> and the module&#8217;s README have the full details.</p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Tue, 06 Oct 2026 22:13:52 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:14:\"Derek Springer\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:39;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:68:\"WordPress.org blog: WordPress 7.1.3 Maintenance and Security Release\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:35:\"https://wordpress.org/news/?p=21753\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:84:\"https://wordpress.org/news/2026/10/wordpress-7-1-3-maintenance-and-security-release/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:5439:\"<p class=\"wp-block-paragraph\">This security and maintenance release features 7 security fixes and <a href=\"https://core.trac.wordpress.org/query?milestone=7.1.3&amp;status=closed&amp;order=priority&amp;col=id&amp;col=summary&amp;col=status&amp;col=milestone&amp;col=owner&amp;col=type&amp;col=priority\">4 bug fixes</a>.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Because this is a security release, it is recommended that you update your sites immediately.</strong></p>\n\n\n\n<p class=\"wp-block-paragraph\">You can <a href=\"https://wordpress.org/wordpress-7.1.3.zip\">download WordPress 7.1.3 from WordPress.org</a>, or visit your WordPress Dashboard, click “Updates”, and then click “Update Now”. If you have sites that support automatic background updates, the update process will begin automatically.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Security updates included in this release</h2>\n\n\n\n<p class=\"wp-block-paragraph\">The security team would like to thank the following people and organizations for responsibly reporting vulnerabilities, and allowing them to be fixed in this release:</p>\n\n\n\n<ul class=\"wp-block-list\">\n<li>A stored XSS on the Comments administration page, exploitable via pending comments, reported by <a href=\"https://trailofbits.com/\">Trail of Bits</a> in collaboration with OpenAI.</li>\n\n\n\n<li>A DoS issue in the <code>WP_Http::make_absolute_url()</code> method, reported by Anthropic</li>\n\n\n\n<li>A second-Order SQL injection in WordPress WXR export, reported by Anthropic</li>\n\n\n\n<li>A weakness allowing Author role users to sticky posts, reported by Anthropic</li>\n\n\n\n<li>Unauthenticated disclosure of comments on private &amp; unpublished posts, reported by <a href=\"https://patchstack.com/\">Ananda Dhakal from Patchstack</a></li>\n\n\n\n<li>Imgur embeds are vulnerable to XSS, reported by <a href=\"https://jackfromeast.github.io/\">Zhengyu Liu</a>, <a href=\"https://jesse-yang.com/\">Jingcheng Yang</a>, and <a href=\"https://gvzhong.github.io/\">Gavin Zhong</a></li>\n\n\n\n<li>Forgeable parameters passed to the <code>{status}_{type}</code> hook can lead to action name collision, reported by Alex Concha of the WordPress security team</li>\n</ul>\n\n\n\n<h2 class=\"wp-block-heading\">Thank you to these WordPress contributors</h2>\n\n\n\n<p class=\"wp-block-paragraph\">This release was led by <a href=\"https://profiles.wordpress.org/whyisjake/\">Jake Spurlock</a>.</p>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 7.1.3 would not have been possible without the contributions of the following people. Their asynchronous coordination to deliver maintenance and security fixes into a stable release is a testament to the power and capability of the WordPress community.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://w.org/@jorbin\">Aaron Jorbin</a>, <a href=\"https://w.org/@adamsilverstein\">Adam Silverstein</a>, <a href=\"https://w.org/@adrianmoldovanwp\">Adi Moldovan</a>, <a href=\"https://w.org/@adrianduffell\">Adrian Duffell</a>, <a href=\"https://w.org/@xknown\">Alex Concha</a>, <a href=\"https://w.org/@arkaprabhachowdhury\">Arkaprabha Chowdhury</a>, <a href=\"https://w.org/@iamchitti\">Deepak Kumar</a>, <a href=\"https://w.org/@donniam\">donniam</a>, <a href=\"https://w.org/@ehtis\">Ehtisham Siddiqui</a>, <a href=\"https://w.org/@whyisjake\">Jake Spurlock</a>, <a href=\"https://w.org/@audrasjb\">Jb Audras</a>, <a href=\"https://w.org/@jeremyfelt\">Jeremy Felt</a>, <a href=\"https://w.org/@joedolson\">Joe Dolson</a>, <a href=\"https://w.org/@johnbillion\">John Blackbourn</a>, <a href=\"https://w.org/@jonsurrell\">Jon Surrell</a>, <a href=\"https://w.org/@desrosj\">Jonathan Desrosiers</a>, <a href=\"https://w.org/@kgagne\">Ken Gagne</a>, <a href=\"https://w.org/@khokansardar\">Khokan Sardar</a>, <a href=\"https://w.org/@lancewillett\">Lance Willett</a>, <a href=\"https://w.org/@lucatume\">lucatume</a>, <a href=\"https://w.org/@marcs0h\">marcs0h</a>, <a href=\"https://w.org/@peterwilsoncc\">Peter Wilson</a>, <a href=\"https://w.org/@paulkevan\">Paul Kevan</a>, <a href=\"https://w.org/@therssoftware\">RS Software</a>, <a href=\"https://w.org/@rfaile313\">Rudy Faile</a>, <a href=\"https://w.org/@sergeybiryukov\">Sergey Biryukov</a>, <a href=\"https://w.org/@siliconforks\">siliconforks</a>, <a href=\"https://w.org/@smerriman\">smerriman</a>, <a href=\"https://w.org/@sabernhardt\">Stephen Bernhardt</a>, <a href=\"https://w.org/@suryakantupadhyay\">Suryakant Upadhyay</a>, <a href=\"https://w.org/@vortfu\">vortfu</a>, <a href=\"https://w.org/@webverts\">webVerts</a>, <a href=\"https://w.org/@westonruter\">Weston Ruter</a>, <a href=\"https://w.org/@yogeshbhutkar\">Yogesh Bhutkar</a></p>\n\n\n\n<h2 class=\"wp-block-heading\">Backports</h2>\n\n\n\n<p class=\"wp-block-paragraph\">As a courtesy, the security fixes are being backported, where necessary, to all branches eligible to receive security fixes (currently through 4.7). As a reminder, <strong>only the most recent version of WordPress is actively supported</strong>. The backports are in progress and will ship as they become ready.</p>\n\n\n\n<h2 class=\"wp-block-heading\">How to contribute</h2>\n\n\n\n<p class=\"wp-block-paragraph\">To get involved in WordPress core development, head over to Trac, <a href=\"https://core.trac.wordpress.org/report/6\">pick a ticket</a>, and join the conversation in the <a href=\"https://wordpress.slack.com/archives/C02RQBWTW\">#core</a> channel. Need help? Check out the <a href=\"https://make.wordpress.org/core/handbook/\">Core Contributor Handbook</a>.</p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Tue, 06 Oct 2026 17:00:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:13:\"Jake Spurlock\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:40;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:123:\"Open Channels FM: Open Source Maintainers Defend Against AI Spam,  Linux Data Trends and WordPress Accessibility Challenges\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2563376\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:128:\"https://openchannels.fm/open-source-maintainers-defend-against-ai-spam-linux-data-trends-and-wordpress-accessibility-challenges/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:130:\"AI-driven growth presents challenges in security and accessibility and infrastructure hurdles that technology teams cannot ignore.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Tue, 06 Oct 2026 15:45:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"Bob Dunn\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:41;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:68:\"Open Channels FM: The Essential Human Touch in Genealogical Research\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2562236\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:75:\"https://openchannels.fm/the-essential-human-touch-in-genealogical-research/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:382:\"As artificial intelligence becomes more integrated into genealogical research, it is tempting to imagine a future where longstanding mysteries are unraveled with a few keystrokes. AI tools can now scan, transcribe, and sort through centuries of records, but the heart of successful genealogy still depends on something machines cannot replicate: the human touch. No matter [&#8230;]\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Tue, 06 Oct 2026 10:42:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:16:\"Open Channels FM\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:42;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:82:\"OpenStation Blog: Someone Said “I Hate OpenStation.” That Was Actually Useful.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:32:\"https://openstation.blog/?p=1400\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:93:\"https://openstation.blog/2026/10/06/someone-said-i-hate-openstation-that-was-actually-useful/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:5333:\"<p class=\"wp-block-paragraph\">A few days ago, someone opened a support thread about <a href=\"https://wordpress.org/plugins/allterrain-forms/\">AllTerrain Forms</a> and, in the middle of otherwise useful feedback, wrote something very direct: “I hate OpenStation.”</p>\n\n\n\n<p class=\"wp-block-paragraph\">Obviously that is not the nicest sentence to read when you are working on the product, but at the same time it immediately got my attention because this is exactly the kind of feedback that can be useful if you don’t take it personally.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So instead of trying to explain why OpenStation is good, or why we made certain decisions, I asked a very simple question: what exactly makes you hate it?</p>\n\n\n\n<p class=\"wp-block-paragraph\">Her answer was actually very good.</p>\n\n\n\n<p class=\"wp-block-paragraph\">She works on a laptop, so screen space matters a lot. OpenStation was opening windows too small for her workflow, which meant that one of her first actions was always maximizing them. She also didn’t like losing the visible URL because she regularly copies URLs into emails, project trackers or messages. On top of that, her users are not very technical, and from her point of view OpenStation was adding another layer to WordPress that she would eventually have to explain and support.</p>\n\n\n\n<p class=\"wp-block-paragraph\">She basically said that browser tabs already exist, users understand them, they use the whole screen, and they don’t hide the URL.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And I think this is exactly where building software becomes interesting, because from our side all of those decisions had reasons behind them, but reasons don’t really matter if the final experience is worse for the person using it.</p>\n\n\n\n<p class=\"wp-block-paragraph\">None of these are theoretical product discussions. They are very concrete things that someone hit while trying to use the software for real work.</p>\n\n\n\n<p class=\"wp-block-paragraph\">That matters a lot to me.</p>\n\n\n\n<p class=\"wp-block-paragraph\">We started discussing these points immediately, and one of them has already made it into the next OpenStation release.</p>\n\n\n\n<figure class=\"wp-block-image aligncenter size-large\"><img alt=\"OpenStation Preferences interface displaying settings for window appearance and behavior, including options for window focus, corners, and dimming effects.\" class=\"wp-image-1403\" height=\"716\" src=\"https://i0.wp.com/openstation.blog/wp-content/uploads/2026/10/image.png?resize=1024%2C716&#038;ssl=1\" width=\"1024\" /></figure>\n\n\n\n<p class=\"wp-block-paragraph\">Users will now be able to choose how new windows open: using the current default behaviour, maximized, or focused. Focused mode maximizes the new window and minimizes the other windows on the same desk, so people working on smaller screens can have something much closer to the experience they expect.</p>\n\n\n\n<p class=\"wp-block-paragraph\">This came directly from that kind of feedback, and the implementation is already merged:</p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://github.com/WordPress/openstation/pull/964\">PR #964: Preferences: choose how newly opened windows appear</a></p>\n\n\n\n<p class=\"wp-block-paragraph\">And this is really the point.</p>\n\n\n\n<p class=\"wp-block-paragraph\">We obviously have our own vision for OpenStation. We believe WordPress can have a much better working environment than the traditional admin experience, and there are many things we still want to explore there. But having a strong idea of where the product should go does not mean pretending every decision we make is correct.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Sometimes the most useful feedback is not “great release” or “this looks amazing”. Sometimes it is someone telling you that a window is too small, that they want the URL back, that something scrolls when it shouldn’t, or simply that they don’t see the benefit of what you built.</p>\n\n\n\n<p class=\"wp-block-paragraph\">That kind of feedback forces you to look at the product from outside your own head, which is probably one of the hardest things to do when you have been working on it every day for months.</p>\n\n\n\n<p class=\"wp-block-paragraph\">For me, OpenStation becoming more mature is not only about adding more apps, more features or more ambitious ideas. A big part of maturity is improving all those small things that make the product feel natural, predictable and less annoying to use.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And I think there is also something important here about open source. People can complain, explain exactly what does not work for them, and a few days later they can literally see the code that changes that behaviour.</p>\n\n\n\n<p class=\"wp-block-paragraph\">That is a pretty healthy way to build software.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So yes, tell us when OpenStation is great, but especially tell us when it sucks. We may not agree with every suggestion, and we obviously cannot build every requested feature, but if there is a real problem behind the feedback, we want to understand it.</p>\n\n\n\n<p class=\"wp-block-paragraph\">In this case, someone said “I hate OpenStation.”</p>\n\n\n\n<p class=\"wp-block-paragraph\">Fair enough.</p>\n\n\n\n<p class=\"wp-block-paragraph\">A few days later, OpenStation got better because of it.</p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Tue, 06 Oct 2026 08:54:53 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:13:\"Daniel López\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:43;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:16:\"Matt: Beeper MCP\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:23:\"https://ma.tt/?p=155119\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:33:\"https://ma.tt/2026/10/beeper-mcp/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:351:\"<p class=\"wp-block-paragraph\">Fellow <a href=\"https://automattic.com/\">Automattician</a> Job Thomas, down in Cape Town, South Africa, has a <a href=\"https://job.blog/2026/09/17/school-communication-is-too-much-so-my-ai-does-it/\">lovely story about using Claude and the Beeper MCP to wrangle all the group chats for his daughter&#8217;s sports</a>.</p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Tue, 06 Oct 2026 06:35:11 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:4:\"Matt\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:44;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:111:\"Open Channels FM: Technology’s Fast Feedback Loop with Triumph of the Nerds, Agile AI, and WordPress Security\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2563290\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:113:\"https://openchannels.fm/technologys-fast-feedback-loop-with-triumph-of-the-nerds-agile-ai-and-wordpress-security/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:88:\"Faster tech means new challenges from AI feedback loops to WordPress security incidents.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Mon, 05 Oct 2026 15:00:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"Bob Dunn\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:45;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:66:\"Open Channels FM: Topics in Tech Business, It’s Rinse and Repeat\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2560606\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:64:\"https://openchannels.fm/topics-in-business-its-rinse-and-repeat/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:78:\"Sometime we think, been there, done that, but hey, not everyone has done that.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Mon, 05 Oct 2026 09:54:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:3:\"Bob\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:46;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:39:\"Akismet: Akismet now supports Drupal 12\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:28:\"http://akismet.com/?p=285135\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:56:\"https://akismet.com/blog/akismet-now-supports-drupal-12/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:4930:\"<figure class=\"wp-block-image size-large\"><img alt=\"\" class=\"wp-image-285145\" height=\"537\" src=\"https://akismet.com/wp-content/uploads/2026/09/ad12-2.png?w=1024\" width=\"1024\" /></figure>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://www.drupal.org/project/akismet_antispam/releases/1.1.0\">Version 1.1.0</a> of the <a href=\"https://www.drupal.org/project/akismet_antispam\">official Akismet Drupal module</a> is out with support for Drupal 12. If you&#8217;re planning your move to 12, spam protection won&#8217;t hold you back. Here are the highlights.</p>\n\n\n\n<h2 class=\"wp-block-heading\" id=\"drupal-12-from-day-one\">Drupal 12 from day one</h2>\n\n\n\n<p class=\"wp-block-paragraph\">The module now runs on Drupal 10.3+, 11 and 12. On Drupal 12, Akismet checks comments and user registrations as soon as you install it, since both live in core. Contact forms, webforms, and the Key module will be supported as soon as they&#8217;re ready for D12.</p>\n\n\n\n<h2 class=\"wp-block-heading\" id=\"what-else-is-new-in-1-1-0\">What else is new in 1.1.0</h2>\n\n\n\n<h3 class=\"wp-block-heading\" id=\"better-spam-scoring\">Better spam scoring</h3>\n\n\n\n<p class=\"wp-block-paragraph\">Every check now gives Akismet a fuller picture of each submission. The module&#8217;s bot detection watches how someone fills out a form: how long they take, how they type, and how they scroll, click or tap. In 1.1.0, all of those signals feed straight into Akismet&#8217;s spam scoring. With more context, Akismet can better tell a real person from a bot, so you should see more spam caught and fewer real messages flagged by mistake.</p>\n\n\n\n<h3 class=\"wp-block-heading\" id=\"better-gdpr-export\">Better GDPR export</h3>\n\n\n\n<p class=\"wp-block-paragraph\"><code>drush akismet:gdpr-export</code> now takes <code>--format=json</code> (or <code>csv</code> and <code>yaml</code>) and returns the full stored record for each match, including the original submission. That makes subject access requests easier to answer completely.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The export also withholds the moderator&#8217;s identity, as GDPR Article 15(4) allows.</p>\n\n\n\n<h3 class=\"wp-block-heading\" id=\"clearer-warnings-about-your-stored-api-key\">Clearer warnings about your stored API key</h3>\n\n\n\n<p class=\"wp-block-paragraph\">The status report now warns you about a leftover copy in yoursettings and stays visible until you deal with it. A new <strong>Delete stored API key</strong> form removes it in one step. You&#8217;ll find the link on the settings page and in the status report.</p>\n\n\n\n<h2 class=\"wp-block-heading\" id=\"coming-from-the-community-module\">Coming from the community module?</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Before the official module, some Drupal sites used the community-maintained <a href=\"https://www.drupal.org/project/akismet\">Akismet module</a> (<code>drupal/akismet</code>). That project is no longer maintained. If you&#8217;re still running it on Drupal 10.3 or later, 1.1.0 can take over your install in place. Your API key, connection timeout and protection settings carry over, and the update prints a report of everything it migrated, changed or dropped. Our <a href=\"https://www.drupal.org/docs/extending-drupal/contributed-modules/contributed-module-documentation/akismet-anti-spam/migrating-from-the-community-akismet-module\">migration guide on drupal.org</a> walks through the process.</p>\n\n\n\n<h2 class=\"wp-block-heading\" id=\"get-started\">Get started</h2>\n\n\n\n<p class=\"wp-block-paragraph\">You&#8217;ll need an Akismet API key. Grab one from our <a href=\"https://akismet.com/pricing/\">pricing page</a>. It&#8217;s free for personal sites.</p>\n\n\n\n<p class=\"wp-block-paragraph\">For a new install:</p>\n\n\n<div class=\"wp-block-syntaxhighlighter-code \"><pre class=\"brush: bash; first-line: 1; gutter: false; title: ; notranslate\">\ncomposer require drupal/akismet_antispam\n</pre></div>\n\n\n<p class=\"wp-block-paragraph\">If you&#8217;re already on 1.0, update the module along with the Akismet PHP SDK it depends on, then run the database updates:</p>\n\n\n<div class=\"wp-block-syntaxhighlighter-code \"><pre class=\"brush: bash; first-line: 1; gutter: false; title: ; notranslate\">\ncomposer update drupal/akismet_antispam --with-dependencies\ndrush updb\n</pre></div>\n\n\n<p class=\"wp-block-paragraph\">The module needs Drupal 10.3, 11 or 12 and PHP 8.1 or newer, or the newer PHP your Drupal core requires.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Found a bug or have an idea? Tell us in the <a href=\"https://www.drupal.org/project/issues/akismet_antispam\">issue queue</a>.</p>\n\n\n\n<p class=\"wp-block-paragraph\">New to the module? Start with our <a href=\"https://akismet.com/blog/introducing-the-official-akismet-drupal-module/\">introduction to the official Akismet Drupal module</a>, or see how it&#8217;s built on the <a href=\"https://akismet.com/blog/introducing-the-official-akismet-php-sdk/\">official Akismet PHP SDK</a>.</p>\n\n\n\n<p class=\"wp-block-paragraph\"></p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Fri, 02 Oct 2026 18:59:59 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:14:\"Derek Springer\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:47;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:93:\"Open Channels FM: Beyond Rants, Productive Discussions and the Mystery of Poor Design Choices\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5: